import SwiftUIstruct CircularProgressView: View {    var progress: Double // Valor entre 0 y 1    var lineWidth: CGFloat = 20    var body: some View {        ZStack {            // Fondo gris            Circle()                .stroke(Color.gray.opacity(0.2), lineWidth: lineWidth)                        // Porción de progreso            Circle()                .trim(from: 0, to: progress)                .stroke(                    AngularGradient(                        gradient: Gradient(colors: [.purple, .blue]),                        center: .center                    ),                    style: StrokeStyle(lineWidth: lineWidth, lineCap: .round)                )                .rotationEffect(.degrees(-90)) // Para iniciar desde arriba                        // Texto en el centro            Text("\(Int(progress * 100))%")                .font(.title2)                .bold()        }        .frame(width: 150, height: 150)    }}